import * as fs from 'fs';
import * as vscode from 'vscode';

/**
 * Types describing the machine-readable schema generated by
 * `scripts/extract_schema.py` from the suanPan manual.
 */

export interface Param {
	index: number;
	required: boolean;
	variadic: boolean;
	end?: number;
	type: string;
	description: string;
	default?: string;
	optionalGroup?: boolean;
}

export interface Form {
	syntax: string;
	keyword: string;
	objectType: string | null;
	invoke: string;
	params: Param[];
}

export interface Entry {
	name: string;
	kind: 'command' | 'type';
	category: string | null;
	summary: string;
	doc: string;
	origin?: string;
	forms: Form[];
}

export interface CategoryInfo {
	path: string;
	description: string;
}

export interface Schema {
	version: number;
	categories: Record<string, CategoryInfo>;
	commands: Record<string, Entry>;
	types: Record<string, Entry>;
	aliasCategory: Record<string, string>;
	dofTokens: string[];
	outputTokens: string[];
	enumOptions: Record<string, string[]>;
}

/**
 * Runtime lookup layer over the generated schema.
 */
export class Registry {
	readonly schema: Schema;
	private readonly commands: Entry[];
	private readonly types: Entry[];
	private readonly categories: Set<string>;
	private readonly typeByCategory = new Map<string, Entry[]>();

	private constructor(schema: Schema) {
		this.schema = schema;
		this.commands = Object.values(schema.commands);
		this.types = Object.values(schema.types);
		this.categories = new Set(Object.keys(schema.categories));
		for (const entry of this.types) {
			const category = entry.category ?? inferCategory(entry);
			if (!category) continue;
			const bucket = this.typeByCategory.get(category);
			if (bucket) bucket.push(entry);
			else this.typeByCategory.set(category, [entry]);
		}
		for (const bucket of this.typeByCategory.values()) bucket.sort((a, b) => a.name.localeCompare(b.name));
	}

	isCategory(word: string): boolean {
		return this.categories.has(word.toLowerCase());
	}

	categoryKeys(): string[] {
		return [...this.categories];
	}

	findCommand(word: string): Entry | undefined {
		return this.schema.commands[word.toLowerCase()];
	}

	findType(word: string): Entry | undefined {
		return this.schema.types[word.toLowerCase()];
	}

	/** Type entries declared under `category` (e.g. all element types). */
	typesOfCategory(category: string): Entry[] {
		return this.typeByCategory.get(category.toLowerCase()) ?? [];
	}

	/** Resolve the object type written as `category <type>`. */
	findTypeInCategory(category: string, word: string): Entry | undefined {
		const entry = this.findType(word);
		if (entry) return entry;
		// fall back to a case-insensitive scan limited to the category
		const lower = word.toLowerCase();
		return this.typesOfCategory(category).find(t => t.name.toLowerCase() === lower);
	}

	/** The object category a command belongs to (handles aliases such as `fix`). */
	categoryOfCommand(word: string): string | undefined {
		const lower = word.toLowerCase();
		if (this.categories.has(lower)) return lower;
		return this.schema.aliasCategory[lower];
	}

	commandEntries(): Entry[] {
		return this.commands;
	}

	typeEntries(): Entry[] {
		return this.types;
	}

	/** Every entry whose name matches `word`, preferring exact matches. */
	lookup(word: string): Entry[] {
		const lower = word.toLowerCase();
		const result: Entry[] = [];
		const command = this.schema.commands[lower];
		if (command) result.push(command);
		const type = this.schema.types[lower];
		if (type) result.push(type);
		return result;
	}

	static fromFile(file: string): Registry {
		const schema = JSON.parse(fs.readFileSync(file, 'utf8')) as Schema;
		return new Registry(schema);
	}

	static fromExtension(context: vscode.ExtensionContext): Registry {
		const file = vscode.Uri.joinPath(context.extensionUri, 'syntaxes', 'commands.json').fsPath;
		return Registry.fromFile(file);
	}
}

/** Fallback used when an entry has no explicit category. */
function inferCategory(entry: Entry): string | undefined {
	for (const form of entry.forms) {
		if (form.objectType) return form.keyword;
	}
	return entry.category ?? undefined;
}
